// collections edge cases: removal during ops, views, stable sorting, groupBy order, associate overwrite, empty cases
fun main() {
    val l = mutableListOf(5, 3, 8, 3, 1); l.remove(3); println(l); l.removeAt(0); println(l); l.removeAll { it > 7 }; println(l); l.retainAll(listOf(3, 1)); println(l); l.addAll(0, listOf(9, 9)); println(l); l.add(1, 4); println(l); println(l.indexOf(9)); println(l.lastIndexOf(9))
    val sub = l.subList(1, 3); println(sub); sub[0] = 100; println(l); l.clear(); println(l.isEmpty()); println(listOf(1, 2, 3, 4, 5).slice(1..3)); println(listOf(1, 2, 3).reversed()); println(listOf(1, 2, 3).take(10)); println(listOf(1, 2, 3).drop(10)); println(listOf(1, 2, 3).takeLast(2)); println(listOf(1, 2, 3).dropLast(1))
    println(listOf("bb", "a", "cc", "d").sortedBy { it.length }); println(listOf("bb", "a", "cc", "d").sortedByDescending { it.length }); println(listOf(3, 1, 2).sortedDescending()); println(listOf("b", "A", "c").sortedWith(String.CASE_INSENSITIVE_ORDER)); println(listOf(1, 2, 3, 4).groupBy { it % 2 }); println(listOf("a", "b", "a").groupingBy { it }.eachCount())
    println(listOf("a" to 1, "a" to 2, "b" to 3).toMap()); println(listOf("a", "bb", "cc").associateBy { it.length }); println(listOf("a", "bb").associate { it to it.length }); println(listOf(1, 2, 3).zip(listOf("a", "b"))); println(listOf(1, 2).zip(listOf(3, 4)) { a, b -> a * b }); println(listOf(1 to "a", 2 to "b").unzip())
    println(emptyList<Int>().sum()); println(emptyList<Int>().maxOrNull()); println(emptyList<Int>().firstOrNull()); println(emptyList<Int>().average()); println(emptyList<String>().joinToString()); println(emptyList<Int>().reduceOrNull { a, b -> a + b }); println(emptyList<Int>().fold(7) { a, b -> a + b }); println(emptyMap<String, Int>().getOrDefault("x", 3))
    println(listOf(1, 2, 3, 4, 5).chunked(2)); println(listOf(1, 2, 3).windowed(2)); println(listOf(1, 2, 3).flatMap { listOf(it, it) }); println(listOf(listOf(1), listOf(2, 3)).flatten()); println(listOf(1, 2, 3).partition { it > 1 }); println(listOf(1, 2, 3, 4).filterIndexed { i, _ -> i % 2 == 0 }); println(listOf(1, 2, 3).mapIndexed { i, v -> i * v }); println(listOf(1, null, 3).mapNotNull { it?.times(2) })
    println(listOf(1, 2, 3) + listOf(4)); println(listOf(1, 2, 3) - listOf(2)); println(listOf(1, 2, 2, 3) - 2); println(setOf(1, 2) + 3); println(setOf(1, 2, 3) - setOf(2)); println(setOf(1, 2) union setOf(2, 3)); println(setOf(1, 2) intersect setOf(2, 3)); println(setOf(1, 2) subtract setOf(2)); println(listOf(1, 2, 2, 3, 3, 3).distinct()); println(listOf("a", "B").distinctBy { it.lowercase() })
    val m = mutableMapOf("a" to 1, "b" to 2); m.getOrPut("c") { 3 }; m.merge("a", 10) { x, y -> x + y }; m.compute("b") { _, v -> v!! * 5 }; println(m); m.remove("a"); println(m.keys); println(m.values); println(m.entries.map { it.key + it.value }); println(m.filter { it.value > 5 }); println(m.mapKeys { it.key.uppercase() }); println(m.toList()); println(m.maxByOrNull { it.value }?.key); println(m.count { it.value > 3 })
    val ll = LinkedHashMap<Int, String>(); ll[3] = "c"; ll[1] = "a"; ll[2] = "b"; ll[3] = "z"; println(ll); println(ll.toSortedMap()); println(ll.keys.sorted()); val dq = ArrayDeque<Int>(); dq.addFirst(1); dq.addLast(2); dq.addFirst(0); println(dq); println(dq.removeFirst()); println(dq.removeLast()); println(dq)
    println(listOf(1, 2, 3).first { it > 1 }); println(listOf(1, 2, 3).last { it < 3 }); println(listOf(1, 2, 3).single { it == 2 }); println(listOf(1, 2, 3).getOrNull(5)); println(listOf(1, 2, 3).elementAtOrElse(7) { -1 }); println(listOf(3, 4).sumOf { it * 2 }); println(listOf("x", "yy").maxBy { it.length }); println(listOf(1, 2, 3).reduceRight { a, b -> a - b }); println(listOf(1, 2, 3).foldRight(0) { a, b -> a - b })
}
